// { [meetId]: { [username]: RTCIceCandidateInit[] } }
// ICE candidates can arrive before the offer/answer → buffered until the remote
// description is set.
const pendingCandidates = {}
// { [meetId]: MediaStream } – local mic + camera stream published to peers
